/**
 * The legal corpus.
 *
 * Cala's prose answer is stitched from whatever it read on the web, which for space law
 * includes blogs. A legal tool cannot present that as authority. So we look up each Law
 * entity Cala names and pull its structured provisions — the actual articulated rule —
 * and that becomes the only evidence the product is allowed to stand on.
 *
 * Entity lookups are rate limited (Cala returns 429), so results are cached on disk and
 * requests are issued one at a time.
 */
import { read, write } from "./cache"

const API = "https://api.cala.ai"

/**
 * The body of space law. Intended to be always-loaded so a claim is not judged
 * unsupported merely because the query did not name its instrument.
 *
 * NOT WIRED IN: loading all six sequentially trips Cala's rate limit and returns an
 * empty corpus, which collapses every claim to "unsupported". See docs/ROADMAP.md item 1.
 */
export const CORE = [
  "Outer Space Treaty",
  "Moon Agreement",
  "Artemis Accords",
  "Rescue Agreement",
  "Liability Convention",
  "Registration Convention",
]

export type Provision = {
  law: string
  officialTitle?: string
  year?: number
  text: string
}

async function call(path: string, init: RequestInit): Promise<any | null> {
  const key = process.env.CALA_API_KEY
  if (!key) throw new Error("CALA_API_KEY is not set")

  for (let attempt = 0; attempt < 3; attempt++) {
    const res = await fetch(`${API}${path}`, {
      ...init,
      headers: { "X-API-KEY": key, "Content-Type": "application/json", ...init.headers },
    })
    if (res.ok) return res.json()
    if (res.status !== 429 && res.status < 500) return null
    await new Promise((r) => setTimeout(r, 1500 * (attempt + 1)))
  }
  return null
}

/** Look up one law and return its provisions, or null if Cala has none. */
async function lookup(name: string): Promise<Provision[] | null> {
  const cacheKey = `law:${name}`
  const cached = await read<Provision[]>(cacheKey)
  if (cached) return cached

  const found = await call(
    `/v1/entities?name=${encodeURIComponent(name)}&entity_types=Law&limit=1`,
    { method: "GET" }
  )
  const entity = found?.entities?.[0]
  if (!entity) return null

  const detail = await call(`/v1/entities/${entity.id}`, {
    method: "POST",
    body: JSON.stringify({
      properties: ["key_provisions", "official_title", "enactment_year"],
    }),
  })
  const props = detail?.properties ?? {}
  const texts: string[] = props.key_provisions?.value ?? []
  if (texts.length === 0) return null

  const provisions = texts.map((text) => ({
    law: entity.name,
    officialTitle: props.official_title?.value,
    year: props.enactment_year?.value,
    text,
  }))
  await write(cacheKey, [], provisions)
  return provisions
}

/** Build the corpus for a set of law names, sequentially to respect the rate limit. */
export async function corpus(names: string[]): Promise<Provision[]> {
  const out: Provision[] = []
  for (const name of names) {
    try {
      const provisions = await lookup(name)
      if (provisions) out.push(...provisions)
    } catch (error) {
      console.warn(`[laws] lookup failed for ${name}:`, error)
    }
  }
  return out
}
/** Cala client: turns a natural-language legal question into structured claims. */

const API = "https://api.cala.ai"

type Origin = { source?: { name?: string; url?: string }; document?: { name?: string; url?: string } }
type ContextEntry = { id: string; content: string; origins?: Origin[] }
type Explain = { content: string; references?: string[] }
type Entity = { id: string; name: string; entity_type: string }

export type Source = { name: string; url: string }
export type Claim = { text: string; sources: Source[] }
export type CalaResult = {
  question: string
  answer: string
  claims: Claim[]
  countries: string[]
  laws: string[]
}

function sourcesFor(byId: Map<string, ContextEntry>, refs: string[] = []): Source[] {
  const out: Source[] = []
  const seen = new Set<string>()
  for (const ref of refs) {
    for (const origin of byId.get(ref)?.origins ?? []) {
      const doc = origin.document ?? origin.source ?? {}
      if (doc.url && !seen.has(doc.url)) {
        seen.add(doc.url)
        out.push({ name: doc.name ?? doc.url, url: doc.url })
      }
    }
  }
  return out
}

export async function ask(question: string): Promise<CalaResult> {
  const key = process.env.CALA_API_KEY
  if (!key) throw new Error("CALA_API_KEY is not set")

  // Cala occasionally returns a transient 5xx. A live demo cannot afford that,
  // so retry server errors with a short backoff.
  let res: Response | null = null
  for (let attempt = 0; attempt < 3; attempt++) {
    res = await fetch(`${API}/v1/knowledge/search`, {
      method: "POST",
      headers: { "X-API-KEY": key, "Content-Type": "application/json" },
      body: JSON.stringify({ input: question }),
    })
    if (res.ok) break
    if (res.status < 500) throw new Error(`Cala returned ${res.status}`)
    console.warn(`[cala] ${res.status} on attempt ${attempt + 1}, retrying`)
    await new Promise((r) => setTimeout(r, 800 * (attempt + 1)))
  }
  if (!res || !res.ok) throw new Error(`Cala unavailable (${res?.status ?? "no response"})`)

  const raw = await res.json()
  const byId = new Map<string, ContextEntry>(
    (raw.context ?? []).map((c: ContextEntry) => [c.id, c])
  )
  const entities: Entity[] = raw.entities ?? []
  const namesOfType = (t: string) =>
    entities.filter((e) => e.entity_type === t).map((e) => e.name)

  return {
    question,
    answer: raw.content ?? "",
    claims: (raw.explainability ?? []).map((e: Explain) => ({
      text: e.content,
      sources: sourcesFor(byId, e.references),
    })),
    countries: namesOfType("Country"),
    laws: namesOfType("Law"),
  }
}

/**
 * Adversarial retrieval.
 *
 * A single query returns the framing of whoever wrote the sources, which for space
 * resources skews toward the states that permit it. A legal tool must not inherit that
 * bias, so we go looking for the opposing position explicitly and merge it in. This is
 * what turns an all-green answer into an honest split.
 */
export async function opposition(question: string): Promise<CalaResult | null> {
  try {
    return await ask(
      `Which states, treaties or legal scholars oppose or reject the following, and why? ${question}`
    )
  } catch (error) {
    console.warn("[cala] opposition lookup failed:", error)
    return null
  }
}
import { NextResponse } from "next/server"
import { ask, opposition } from "@/lib/mooneto/cala"
import { analyse, type Answer } from "@/lib/mooneto/classify"
import { standalone } from "@/lib/mooneto/rewrite"
import { read, write } from "@/lib/mooneto/cache"
import { buildPlan, wantsPlan } from "@/lib/mooneto/plan"
import { corpus } from "@/lib/mooneto/laws"

export const runtime = "nodejs"
export const maxDuration = 120

export async function POST(request: Request) {
  const started = Date.now()
  try {
    const { question, history = [], gathered = null } = await request.json()
    if (!question?.trim()) {
      return NextResponse.json({ error: "question is required" }, { status: 400 })
    }

    const asked = question.trim()

    // Check the cache before the rewrite: the rewrite itself costs a model call.
    const cached = await read<Answer>(asked, history)
    if (cached) {
      console.log(`[mooneto] cache hit (${Date.now() - started}ms)`)
      return NextResponse.json({ ...cached, asked, cached: true })
    }

    const resolved = await standalone(asked, history)
    if (resolved !== asked) console.log(`[mooneto] rewrote -> ${resolved}`)

    // Ask the question, and in parallel ask who disagrees. Merging both keeps a
    // one-sided source set from producing a falsely settled answer.
    const [found, against] = await Promise.all([ask(resolved), opposition(resolved)])
    if (against) {
      found.claims.push(...against.claims)
      found.countries = [...new Set([...found.countries, ...against.countries])]
      found.laws = [...new Set([...found.laws, ...against.laws])]
    }

    // The legal corpus: the articulated provisions of every instrument Cala named.
    // Claims are judged against this and nothing else.
    const provisions = await corpus(found.laws)
    console.log(`[mooneto] corpus: ${provisions.length} provision(s) from ${found.laws.length} law(s)`)

    const analysed = await analyse(found, provisions)
    // A request for a decision gets a memo, not a claim list.
    // Fold in everything established earlier in the thread, so the memo reasons over the
    // whole case file rather than only the last question's findings.
    const caseFile = gathered
      ? {
          ...analysed,
          laws: [...new Set([...analysed.laws, ...(gathered.laws ?? [])])],
          countries: [
            ...analysed.countries,
            ...(gathered.countries ?? []).filter(
              (c: any) => !analysed.countries.some((k) => k.name === c.name)
            ),
          ],
        }
      : analysed
    const plan = wantsPlan(asked) ? await buildPlan(asked, caseFile) : null
    const answer = { ...analysed, resolved, ...(plan ? { plan, verdict: plan.verdict } : {}) }
    await write(asked, history, answer)
    console.log(`[mooneto] fresh (${Date.now() - started}ms)`)
    return NextResponse.json({ ...answer, asked, resolved, cached: false })
  } catch (error: any) {
    console.error("[mooneto]", error)
    return NextResponse.json({ error: error.message ?? "failed" }, { status: 500 })
  }
}
{
  "name": "mooneto",
  "version": "0.1.0",
  "private": true,
  "scripts": {
    "dev": "next dev -p 3005",
    "build": "next build",
    "start": "next start"
  },
  "dependencies": {
    "next": "15.5.2",
    "react": "19.1.1",
    "react-dom": "19.1.1"
  },
  "devDependencies": {
    "@types/node": "^22",
    "@types/react": "^19",
    "typescript": "^5"
  }
}

