                      <div className="memo">
                        <h3>Recommended route</h3>
                        <ol>
                          {turn.a.plan.route.map((r, j) => (
                            <li key={j}>
                              {r.step}
                              <span className="basis">{r.basis}</span>
                            </li>
                          ))}
                        </ol>

                        <h3>Open risks</h3>
                        <ul className="risks">
                          {turn.a.plan.risks.map((r, j) => (
                            <li key={j}>
                              {r.risk}
                              <span className="basis">changes if: {r.trigger}</span>
                            </li>
                          ))}
                        </ul>

                        <h3>Legal confidence</h3>
                        <dl className="conf">
                          <dt>Ratification</dt>
                          <dd>{turn.a.plan.confidence.ratification}</dd>
                          <dt>National law</dt>
                          <dd>{turn.a.plan.confidence.nationalLaw}</dd>
                          <dt>Major-power dissent</dt>
                          <dd>{turn.a.plan.confidence.dissent}</dd>
                        </dl>
                      </div>
                    )}
                    {!turn.a.plan && turn.a.claims.map((c, j) => (
                      <div className="claim" key={j}>
                        <span className={`tag ${c.label}`}>{c.label}</span>
                        <p>{c.text}</p>
                        {c.why && <p className="why">{c.why}</p>}
                        {c.sources.length > 0 && (
                          <div className="src">
                            {c.sources.map((s, k) => (
                              <a key={k} href={s.url} target="_blank" rel="noreferrer">
                                {new URL(s.url).hostname.replace("www.", "")}
                              </a>
                            ))}
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                )}
              </div>
            ))}
            {busy && <div className="a">Consulting treaties…</div>}
            <div ref={bottom} />
          </div>

          <form
            onSubmit={(e) => {
              e.preventDefault()
              submit(input)
            }}
          >
            <input
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Ask about doing business in space…"
            />
            <button type="submit" disabled={busy}>
              Ask
            </button>
          </form>
        </section>

        <section className="stage">
          <div className="moon" />

          {latest && (
            <div className={`verdict ${latest.tone}`}>{latest.verdict}</div>
          )}

          {latest && latest.laws.length > 0 && (
            <div className="laws">
              {latest.laws.map((law, i) => (
                <div className="law" key={law} style={{ animationDelay: `${i * 90}ms` }}>
                  <span className="ico">📜</span>
                  <span className="name">{law}</span>
                </div>
              ))}
            </div>
          )}

          {latest && latest.countries.length > 0 && (
            <div className="flags">
              {latest.countries.map((c, i) => (
                <div
                  className={`flag ${c.stance}`}
                  key={c.name}
                  title={c.why}
                  style={{ animationDelay: `${i * 70}ms` }}
                >
                  <span className="em">{flag(c.name)}</span>
                  <span>{c.name}</span>
                  <span className="st">{c.stance}</span>
                </div>
              ))}
            </div>
          )}
        </section>
      </div>
    </>
  )
}
:root{
  --bg:#05060d; --panel:#0c0f1c; --line:#1d2337;
  --ink:#e8ecf8; --dim:#8891ad;
  --settled:#31c48d; --disputed:#f5b53f; --unsupported:#6b7490;
  --rejects:#e8556d;
}
*{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%}
body{
  background:var(--bg); color:var(--ink);
  font:15px/1.55 ui-sans-serif,-apple-system,"Segoe UI",Roboto,sans-serif;
  overflow:hidden;
}
.stars{
  position:fixed; inset:0; pointer-events:none; opacity:.5;
  background:
    radial-gradient(1.5px 1.5px at 20% 30%,#fff,transparent),
    radial-gradient(1.5px 1.5px at 70% 15%,#fff,transparent),
    radial-gradient(1px 1px at 45% 70%,#fff,transparent),
    radial-gradient(1.5px 1.5px at 85% 55%,#fff,transparent),
    radial-gradient(1px 1px at 10% 80%,#fff,transparent),
    radial-gradient(1px 1px at 60% 90%,#fff,transparent),
    radial-gradient(1.5px 1.5px at 35% 45%,#fff,transparent);
}
.grid{display:grid; grid-template-columns:minmax(380px,470px) 1fr; height:100vh; position:relative}

.chat{display:flex; flex-direction:column; border-right:1px solid var(--line);
      background:var(--panel); min-height:0}
.chat header{padding:22px 24px 16px; border-bottom:1px solid var(--line)}
.chat h1{font-size:22px; letter-spacing:-.02em}
.chat header p{color:var(--dim); font-size:13px; margin-top:6px}
.chat header em{color:var(--ink); font-style:normal}
.thread{flex:1; overflow-y:auto; padding:18px 24px; display:flex;
        flex-direction:column; gap:18px; min-height:0}
.hint p{color:var(--dim); font-size:11px; text-transform:uppercase;
        letter-spacing:.09em; margin-bottom:10px}
.suggest{display:block; width:100%; text-align:left; margin-bottom:8px; cursor:pointer;
  background:transparent; border:1px solid var(--line); color:var(--dim);
  border-radius:9px; padding:10px 12px; font:inherit; font-size:13px}
.suggest:hover{border-color:var(--settled); color:var(--ink)}

.q{align-self:flex-end; background:#20304f; border-radius:12px 12px 3px 12px;
   padding:10px 14px; max-width:88%}
.a{border-left:2px solid var(--line); padding-left:14px}
.a .lead{font-size:16px; margin-bottom:14px; line-height:1.4}

.claim{padding:9px 0; border-top:1px solid var(--line)}
.claim:first-of-type{border-top:0}
.tag{display:inline-block; font-size:10px; letter-spacing:.1em; text-transform:uppercase;
     padding:2px 7px; border-radius:20px; margin-bottom:5px; font-weight:600}
.tag.settled{background:rgba(49,196,141,.14); color:var(--settled)}
.tag.disputed{background:rgba(245,181,63,.14); color:var(--disputed)}
.tag.unsupported{background:rgba(107,116,144,.16); color:var(--unsupported)}
.claim p{font-size:13.5px; color:#c9d1e6}
.claim .why{color:var(--dim); font-size:12px; font-style:italic; margin-top:3px}
.src{margin-top:6px; display:flex; flex-wrap:wrap; gap:8px}
.src a{color:var(--dim); font-size:11px; text-decoration:none; border-bottom:1px dotted var(--dim)}
.src a:hover{color:var(--settled); border-color:var(--settled)}
.err{color:var(--rejects); font-size:13px}

form{display:flex; gap:9px; padding:16px 24px; border-top:1px solid var(--line)}
form input{flex:1; background:#111527; border:1px solid var(--line); color:var(--ink);
  border-radius:9px; padding:11px 13px; font:inherit}
form input:focus{outline:none; border-color:var(--settled)}
form button{background:var(--settled); color:#04120c; border:0; border-radius:9px;
  padding:0 18px; font:inherit; font-weight:600; cursor:pointer}
form button:disabled{opacity:.4; cursor:wait}

.stage{position:relative; display:flex; flex-direction:column; align-items:center;
       justify-content:center; gap:26px; padding:40px; overflow-y:auto}
.moon{width:190px; height:190px; border-radius:50%;
  background:radial-gradient(circle at 34% 30%,#cfd4e0 0%,#9aa1b4 45%,#5a6076 78%,#33384a 100%);
  box-shadow:0 0 90px rgba(180,195,235,.22), inset -16px -12px 44px rgba(0,0,0,.55);
  position:relative; transition:transform .6s ease; flex:none}
.moon::after{content:""; position:absolute; inset:0; border-radius:50%; opacity:.32;
  background:
    radial-gradient(9px 9px at 30% 34%,#6a7086,transparent),
    radial-gradient(14px 14px at 63% 52%,#6a7086,transparent),
    radial-gradient(7px 7px at 47% 71%,#6a7086,transparent),
    radial-gradient(5px 5px at 72% 26%,#6a7086,transparent)}
.busy .moon{transform:scale(.93)}

.verdict{max-width:600px; text-align:center; font-size:19px; line-height:1.45;
         letter-spacing:-.01em}
.verdict.no{color:var(--rejects)}
.verdict.split{color:var(--disputed)}
.verdict.yes{color:var(--settled)}

.laws{display:flex; flex-wrap:wrap; gap:12px; justify-content:center; max-width:780px}
.law{width:136px; padding:14px 12px; border:1px solid var(--line); border-radius:11px;
  background:linear-gradient(#111527,#0a0d18); text-align:center; animation:rise .45s ease backwards}
.law .ico{font-size:24px; display:block; margin-bottom:7px}
.law .name{font-size:12px; line-height:1.35; color:#c9d1e6}

.flags{display:flex; flex-wrap:wrap; gap:10px; justify-content:center; max-width:840px}
.flag{display:flex; align-items:center; gap:8px; padding:8px 13px; border-radius:22px;
  border:1px solid var(--line); background:#0a0d18; font-size:13px;
  animation:rise .45s ease backwards}
.flag .em{font-size:19px}
.flag.enables{border-color:rgba(49,196,141,.5)}
.flag.rejects{border-color:rgba(232,85,109,.5)}
.flag.enables .st{color:var(--settled)}
.flag.rejects .st{color:var(--rejects)}
.flag.unclear .st{color:var(--unsupported)}
.flag .st{font-size:10px; text-transform:uppercase; letter-spacing:.07em}

@keyframes rise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}

.a .resolved{color:var(--dim); font-size:11.5px; font-style:italic; margin:-8px 0 12px}

/* ---- decision memo (beat 3) ---- */
.memo h3{font-size:11px; text-transform:uppercase; letter-spacing:.09em;
  color:var(--dim); margin:16px 0 8px; font-weight:600}
.memo h3:first-child{margin-top:4px}
.memo ol,.memo ul{margin:0; padding-left:18px; display:flex; flex-direction:column; gap:9px}
.memo li{font-size:13.5px; color:#c9d1e6}
.memo .basis{display:block; color:var(--dim); font-size:11.5px; font-style:italic; margin-top:2px}
.memo .risks li::marker{color:var(--disputed)}
.memo ol li::marker{color:var(--settled); font-weight:600}
.conf{display:grid; grid-template-columns:auto 1fr; gap:5px 12px; margin:0; font-size:12.5px}
.conf dt{color:var(--dim); white-space:nowrap}
.conf dd{margin:0; color:#c9d1e6}

